  type CommonGroundHoldReason,
  type CommonGroundPoint
} from './commonGroundState.ts';

export interface CommonGroundAabb {
  readonly name: string;
  readonly lo: CommonGroundPoint;
  readonly hi: CommonGroundPoint;
}

